<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
$root=dirname(__DIR__);$items=[];
$add=static function(string $s,string $file,string $kind)use(&$items){$s=trim(html_entity_decode($s,ENT_QUOTES|ENT_HTML5,'UTF-8'));if(!preg_match('/[A-Za-z]/',$s)||strlen($s)>3000||str_contains($s,'<?'))return;$items[$s]['files'][$file]=true;$items[$s]['kinds'][$kind]=true;};
foreach(glob($root.'/app/Views/*.php') as $file){foreach(token_get_all(file_get_contents($file)) as $token){if(!is_array($token))continue;if($token[0]===T_INLINE_HTML){preg_match_all('/>([^<>]+)</u',$token[1],$m);foreach($m[1] as $v)$add($v,basename($file),'html');preg_match_all('/(?:placeholder|aria-label|title|alt)="([^"]+)"/u',$token[1],$m);foreach($m[1] as $v)$add($v,basename($file),'attribute');}elseif($token[0]===T_CONSTANT_ENCAPSED_STRING){$v=substr($token[1],1,-1);if(preg_match('/^[A-Z+][A-Za-z0-9 (),\/:.%&+—–’!?−≥<>-]*[a-z][A-Za-z0-9 (),\/:.%&+—–’!?−≥<>-]*$/u',$v)&&!preg_match('/^(SELECT|INSERT|UPDATE|DELETE|CREATE|ALTER|SET|JOIN|WHERE|UTC_|APP_|Content-|Cache-|Location:)/',$v))$add($v,basename($file),'php');}}}
foreach(array_merge(glob($root.'/app/Services/*.php'),glob($root.'/app/Controllers/*.php'),glob($root.'/app/Support/*Exception.php')) as $file){foreach(token_get_all(file_get_contents($file)) as $token)if(is_array($token)&&$token[0]===T_CONSTANT_ENCAPSED_STRING){$v=str_replace(["\\'",'\\"'],["'",'"'],substr($token[1],1,-1));if(preg_match('/^[A-Z][a-z][^<>\r\n]*[ .!?]$/u',$v)&&!str_contains($v,'SELECT ')&&!str_contains($v,' FROM ')&&!str_contains($v,'=>'))$add($v,basename($file),'message');}}
ksort($items);$out=[];foreach($items as $key=>$v)$out[]=['text'=>$key,'files'=>array_keys($v['files']),'kinds'=>array_keys($v['kinds'])];file_put_contents($root.'/storage/localization-audit.json',json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));echo count($out)." unique server display strings audited.\n";
